import { createStore } from "redux";

const initialState = {
  balance: 0,
  loan: 0,
  loanPurpose: "",
};

function reducer(state = initialState, action) {
  switch (action.type) {
    case "account/depost":
      return { ...state, balance: state.balance + action.payloud };
    case "account/withdraw":
      return { ...state, balance: state.balance - action.payloud };
    case "account/requestLoan":
      if (state.loan > 0) return state;
      return {
        ...state,
        loan: action.payloud.amount,
        loanPurpose: action.payloud.loanPurpose,
        balance: state.balance + action.payloud.amount,
      };
    case "account/payLoan":
      if (state.balance >= state.loan)
        return {
          ...state,
          loanPurpose: "",
          balance: state.balance - state.loan,
          loan: 0,
        };
      return state;

    default:
      throw new Error(`${action.type}Unknown account reducer type was made`);
  }
}

function depost(amount) {
  return { type: "account/depost", payloud: amount };
}

function withdraw(amount) {
  return { type: "account/withdraw", payloud: amount };
}

function requestLoan(amount, purpose) {
  return {
    type: "account/requestLoan",
    payloud: { amount, loanPurpose: purpose },
  };
}

function payLoan() {
  return {
    type: "account/payLoan",
  };
}

const store = createStore({ reducer });

export { store, depost, withdraw, requestLoan, payLoan };
